// Adaptive Sorting Algorithm Implementation
// This program implements a sorting algorithm that can be evolved to adapt to different data patterns



// EVOLVE-BLOCK-START
// Initial implementation: Simple quicksort
// This can be evolved to:
// - Hybrid algorithms (introsort, timsort-like)
// - Adaptive pivot selection
// - Special handling for nearly sorted data
// - Switching to different algorithms based on data characteristics

pub fn adaptive_sort<T: Ord>(arr: &mut [T]) {
    let len = arr.len();
    if len <= 1 { return; }
    let max_depth = (2.0 * (len as f64).log2()) as usize;
    introsort(arr, 0, len - 1, max_depth);
}

fn introsort<T: Ord>(arr: &mut [T], low: usize, high: usize, depth: usize) {
    if high <= low { return; }
    let len = high - low + 1;
    if len <= 16 { insertion_sort_range(arr, low, high); return; }
    if depth == 0 { heap_sort_range(arr, low, high); return; }

    // Hoare partition returns split index j such that [low..=j] <= [j+1..=high]
    let j = partition(arr, low, high);
    if j > low { introsort(arr, low, j, depth - 1); }
    introsort(arr, j + 1, high, depth - 1);
}

fn median_of_three<T: Ord>(arr: &mut [T], low: usize, high: usize) {
    let mid = low + (high - low) / 2;
    if arr[mid] < arr[low] { arr.swap(low, mid); }
    if arr[high] < arr[low] { arr.swap(low, high); }
    if arr[high] < arr[mid] { arr.swap(mid, high); }
    // After this, arr[mid] is the median; move it to low for Hoare partition pivot.
    arr.swap(low, mid);
}

fn partition<T: Ord>(arr: &mut [T], low: usize, high: usize) -> usize {
    if high - low >= 2 { median_of_three(arr, low, high); }
    let mut i = low;
    let mut j = high;
    loop {
        while arr[i] < arr[low] { i += 1; }
        while arr[j] > arr[low] { j -= 1; }
        if i >= j { return j; }
        arr.swap(i, j);
        i += 1;
        if j == 0 { return 0; } // safety for usize underflow (practically unreachable with low==0)
        j -= 1;
    }
}

fn insertion_sort_range<T: Ord>(arr: &mut [T], low: usize, high: usize) {
    for i in (low + 1)..=high {
        let mut j = i;
        while j > low && arr[j - 1] > arr[j] {
            arr.swap(j, j - 1);
            j -= 1;
        }
    }
}

fn heap_sort_range<T: Ord>(arr: &mut [T], low: usize, high: usize) {
    let len = high - low + 1;
    for i in (0..len / 2).rev() {
        sift_down(arr, low, i, len);
    }
    for i in (1..len).rev() {
        arr.swap(low, low + i);
        sift_down(arr, low, 0, i);
    }
}

fn sift_down<T: Ord>(arr: &mut [T], base: usize, start: usize, len: usize) {
    let mut root = start;
    loop {
        let child = 2 * root + 1;
        if child >= len { break; }
        let mut swap = root;
        if arr[base + child] > arr[base + swap] { swap = child; }
        if child + 1 < len && arr[base + child + 1] > arr[base + swap] { swap = child + 1; }
        if swap == root { break; }
        arr.swap(base + root, base + swap);
        root = swap;
    }
}
// EVOLVE-BLOCK-END

// Benchmark function to test the sort implementation
pub fn run_benchmark(test_data: Vec<Vec<i32>>) -> BenchmarkResults {
    let mut results = BenchmarkResults {
        times: Vec::new(),
        correctness: Vec::new(),
        adaptability_score: 0.0,
    };

    for data in test_data {
        let mut arr = data.clone();
        let start = std::time::Instant::now();

        adaptive_sort(&mut arr);

        let elapsed = start.elapsed();
        results.times.push(elapsed.as_secs_f64());

        // Check if correctly sorted
        let is_sorted = arr.windows(2).all(|w| w[0] <= w[1]);
        results.correctness.push(is_sorted);
    }

    // Calculate adaptability score based on performance variance
    if results.times.len() > 1 {
        let mean_time: f64 = results.times.iter().sum::<f64>() / results.times.len() as f64;
        let variance: f64 = results.times.iter()
            .map(|t| (t - mean_time).powi(2))
            .sum::<f64>() / results.times.len() as f64;

        // Lower variance means better adaptability
        results.adaptability_score = 1.0 / (1.0 + variance.sqrt());
    }

    results
}

#[derive(Debug)]
pub struct BenchmarkResults {
    pub times: Vec<f64>,
    pub correctness: Vec<bool>,
    pub adaptability_score: f64,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_basic_sort() {
        let mut arr = vec![3, 1, 4, 1, 5, 9, 2, 6];
        adaptive_sort(&mut arr);
        assert_eq!(arr, vec![1, 1, 2, 3, 4, 5, 6, 9]);
    }

    #[test]
    fn test_empty_array() {
        let mut arr: Vec<i32> = vec![];
        adaptive_sort(&mut arr);
        assert_eq!(arr, vec![]);
    }

    #[test]
    fn test_single_element() {
        let mut arr = vec![42];
        adaptive_sort(&mut arr);
        assert_eq!(arr, vec![42]);
    }
}
